// Generated offline. Per study species and variable, the ground truth of the
// impression task ("can this species tolerate the variable's low / high end?").
// Over every plant species (quality-filtered observations: not obscured, <= 500 m
// coordinate uncertainty) that has at least 10 values for the variable, each
// species' 1st and 99th percentile of the variable is taken as its practical low
// and high extreme (trimmed so a stray misidentified record can't set it). The
// tolerance percentiles then rank those extremes across the whole pool (0-1;
// ties share their mid-rank): the lower a species' 1st percentile, the more
// tolerant of the low end; the higher its 99th, the more tolerant of the high
// end. Values are in the study's display units (imperial: F for bio1, inches for
// bio12). Note these extremes use all of a species' quality-filtered
// observations, not only those inside its map window.

import type { StudyVariableId } from '@/components/sections/studyVariables';

export type VariableExtremes = {
  /** 1st / 99th percentile of the species' values. */
  low: number;
  high: number;
  /** Tolerance percentile (0-1, higher = more tolerant) of each end. */
  lowTolerance: number;
  highTolerance: number;
};

type Cell = [number, number, number, number] | null;
type Raw = [string, ...Cell[]];

const ORDER: StudyVariableId[] = ['bio1', 'bio12', 'rsdsmean', 'scdur', 'cfvo'];

