export const STAGE_EXTREMES: Record<
  string,
  Partial<Record<StudyVariableId, VariableExtremes>>
> = Object.fromEntries(
  RAW.map(([id, ...cells]) => {
    const extremes: Partial<Record<StudyVariableId, VariableExtremes>> = {};
    ORDER.forEach((variable, i) => {
      const cell = cells[i];
      if (cell) {
        extremes[variable] = {
          low: cell[0],
          high: cell[1],
          lowTolerance: cell[2],
          highTolerance: cell[3],
        };
      }
    });
    return [id, extremes];
  }),
);
